import { getContext, setContext } from "svelte";

const fieldContextKey = Symbol("coss-svelte-field");

export type FieldContext = {
	baseId: string;
	controlId: string;
	labelId: string;
	descriptionId: string;
	errorId: string;
	validityId: string;
	hasLabel: boolean;
	required: boolean;
	disabled: boolean;
	invalid: boolean;
	describedBy: string;
	registerLabel: (id?: string) => () => void;
	registerDescription: (id?: string) => () => void;
	registerError: (id?: string) => () => void;
};

export function createFieldContext(
	baseId: string,
	defaults: {
		required: () => boolean;
		disabled: () => boolean;
		invalid: () => boolean;
		label?: () => boolean;
		description?: () => boolean;
		error?: () => boolean;
	}
): FieldContext {
	let labels = $state<string[]>([]);
	let descriptions = $state<string[]>(defaults.description?.() ? [`${baseId}-description`] : []);
	let errors = $state<string[]>(defaults.error?.() ? [`${baseId}-error`] : []);
	const register = (items: string[], id: string | undefined) => {
		if (id && !items.includes(id)) items.push(id);
		return () => {
			const index = id ? items.indexOf(id) : -1;
			if (index >= 0) items.splice(index, 1);
		};
	};

	return {
		baseId,
		controlId: `${baseId}-control`,
		labelId: `${baseId}-label`,
		descriptionId: `${baseId}-description`,
		errorId: `${baseId}-error`,
		validityId: `${baseId}-validity`,
		get hasLabel() {
			return (defaults.label?.() ?? false) || labels.length > 0;
		},
		get required() {
			return defaults.required();
		},
		get disabled() {
			return defaults.disabled();
		},
		get invalid() {
			return defaults.invalid();
		},
		get describedBy() {
			return [...descriptions, ...errors].join(" ");
		},
		registerLabel: (id = `${baseId}-label`) => register(labels, id),
		registerDescription: (id = `${baseId}-description`) => register(descriptions, id),
		registerError: (id = `${baseId}-error`) => register(errors, id),
	};
}

export function setFieldContext(context: FieldContext): void {
	setContext(fieldContextKey, context);
}

export function getFieldContext(): FieldContext | undefined {
	return getContext<FieldContext | undefined>(fieldContextKey);
}

export function mergeFieldIds(...values: Array<string | null | undefined>): string | undefined {
	const ids = new Set<string>();
	for (const value of values) {
		for (const id of value?.split(/\s+/u) ?? []) {
			if (id) ids.add(id);
		}
	}
	return ids.size > 0 ? [...ids].join(" ") : undefined;
}

export const NUMBER_FIELD_PRESS_DELAY = 400;
export const NUMBER_FIELD_REPEAT_INTERVAL = 80;
export const NUMBER_FIELD_SCRUB_THRESHOLD = 8;
export const NUMBER_FIELD_MAX_PRECISION = 12;

export type NumberFieldReason =
	| "input"
	| "increment"
	| "decrement"
	| "keyboard"
	| "wheel"
	| "scrub"
	| "reset";

export type NumberFieldChangeDetails = Readonly<{
	reason: NumberFieldReason;
	previousValue: number | null;
	sourceEvent: Event | null;
}>;

export type NumberFieldDirection = -1 | 1;

export type NumberFieldConfig = Readonly<{
	min?: number;
	max?: number;
	step: number;
	smallStep: number;
	largeStep: number;
}>;

export type NumberFieldLocale = Readonly<{
	decimal: string;
	group?: string;
	minus: string;
	plus: string;
	digits: ReadonlyMap<string, string>;
}>;

export type ParsedNumberEdit =
	| { kind: "empty" }
	| { kind: "sign" }
	| { kind: "trailing-decimal"; value: number }
	| { kind: "number"; value: number }
	| { kind: "invalid" };

type NumberFieldConfigInput = Partial<NumberFieldConfig>;

function assertFiniteOption(name: string, value: number | undefined): void {
	if (value !== undefined && !Number.isFinite(value)) {
		throw new TypeError(`NumberField ${name} must be a finite number.`);
	}
}

function assertPositiveStep(name: string, value: number): void {
	if (!Number.isFinite(value) || value <= 0) {
		throw new TypeError(`NumberField ${name} must be a finite number greater than zero.`);
	}
}

export function validateNumberFieldConfig({
	min,
	max,
	step = 1,
	smallStep = 0.1,
	largeStep = 10,
}: NumberFieldConfigInput = {}): NumberFieldConfig {
	assertFiniteOption("min", min);
	assertFiniteOption("max", max);
	assertPositiveStep("step", step);
	assertPositiveStep("smallStep", smallStep);
	assertPositiveStep("largeStep", largeStep);

	if (min !== undefined && max !== undefined && min > max) {
		throw new TypeError("NumberField min must be less than or equal to max.");
	}

	return { min, max, step, smallStep, largeStep };
}

export function assertNumberFieldValue(value: number | null, name = "value"): number | null {
	if (value === null) return null;
	if (!Number.isFinite(value)) {
		throw new TypeError(`NumberField ${name} must be a finite number or null.`);
	}

	return value;
}

export function clampNumberFieldValue(
	value: number,
	{ min, max }: Pick<NumberFieldConfig, "min" | "max">
): number {
	return Math.min(
		max ?? Number.POSITIVE_INFINITY,
		Math.max(min ?? Number.NEGATIVE_INFINITY, value)
	);
}

export function isNumberFieldValueOutOfBounds(
	value: number | null,
	{ min, max }: Pick<NumberFieldConfig, "min" | "max">
): boolean {
	return (
		value !== null && ((min !== undefined && value < min) || (max !== undefined && value > max))
	);
}

export function decimalPrecision(value: number): number {
	const [coefficient, exponentSource] = value.toString().toLowerCase().split("e");
	const exponent = Number(exponentSource ?? 0);
	const fractionLength = coefficient.split(".")[1]?.length ?? 0;
	return Math.min(NUMBER_FIELD_MAX_PRECISION, Math.max(0, fractionLength - exponent));
}

function roundToPrecision(value: number, precision: number): number {
	if (!Number.isFinite(value)) return value;
	const scale = 10 ** Math.min(NUMBER_FIELD_MAX_PRECISION, Math.max(0, precision));
	return Math.round((value + Number.EPSILON * Math.sign(value || 1)) * scale) / scale;
}

function isGridAligned(quotient: number): boolean {
	const nearest = Math.round(quotient);
	const tolerance = Number.EPSILON * Math.max(1, Math.abs(quotient)) * 8;
	return Math.abs(quotient - nearest) <= tolerance;
}

export function alignNumberFieldValue(
	value: number,
	step: number,
	config: Pick<NumberFieldConfig, "min" | "max">
): number {
	const base = config.min ?? 0;
	const quotient = (value - base) / step;
	const precision = Math.max(
		decimalPrecision(base),
		decimalPrecision(step),
		decimalPrecision(value)
	);
	const aligned = roundToPrecision(base + Math.round(quotient) * step, precision);
	return clampNumberFieldValue(aligned, config);
}

export function stepNumberFieldValue(
	value: number | null,
	direction: NumberFieldDirection,
	amount: number,
	config: Pick<NumberFieldConfig, "min" | "max">
): number {
	assertPositiveStep("step amount", amount);
	const current = value ?? 0;
	const base = config.min ?? 0;
	const quotient = (current - base) / amount;
	const gridIndex = isGridAligned(quotient)
		? Math.round(quotient) + direction
		: direction > 0
			? Math.floor(quotient) + 1
			: Math.ceil(quotient) - 1;
	const precision = Math.max(
		decimalPrecision(current),
		decimalPrecision(base),
		decimalPrecision(amount)
	);
	const next = roundToPrecision(base + gridIndex * amount, precision);
	return clampNumberFieldValue(next, config);
}

export function isNumberFieldStepDisabled({
	value,
	direction,
	amount,
	config,
	disabled = false,
	readonly = false,
}: {
	value: number | null;
	direction: NumberFieldDirection;
	amount: number;
	config: Pick<NumberFieldConfig, "min" | "max">;
	disabled?: boolean;
	readonly?: boolean;
}): boolean {
	if (disabled || readonly) return true;
	if (value === null) return false;
	return Object.is(stepNumberFieldValue(value, direction, amount, config), value);
}

export function createNumberFieldLocale(locale: string | string[]): NumberFieldLocale {
	const plainFormatter = new Intl.NumberFormat(locale, {
		maximumFractionDigits: NUMBER_FIELD_MAX_PRECISION,
		useGrouping: false,
	});
	const groupedFormatter = new Intl.NumberFormat(locale);
	const signedFormatter = new Intl.NumberFormat(locale, {
		signDisplay: "always",
		useGrouping: false,
	});
	const sample = plainFormatter.formatToParts(-1.1);
	const group = groupedFormatter.formatToParts(10_000).find((part) => part.type === "group")?.value;
	const digits = new Map<string, string>();

	for (let digit = 0; digit <= 9; digit += 1) {
		const localizedDigit = plainFormatter
			.formatToParts(digit)
			.find((part) => part.type === "integer")?.value;
		if (localizedDigit) digits.set(localizedDigit, String(digit));
	}

	return {
		decimal: sample.find((part) => part.type === "decimal")?.value ?? ".",
		group,
		minus: sample.find((part) => part.type === "minusSign")?.value ?? "-",
		plus: signedFormatter.formatToParts(1).find((part) => part.type === "plusSign")?.value ?? "+",
		digits,
	};
}

function replaceAllLiteral(value: string, search: string | undefined, replacement: string): string {
	return search ? value.split(search).join(replacement) : value;
}

function normalizeLocalizedEdit(value: string, locale: NumberFieldLocale): string {
	let normalized = value.replace(/[\s\u00a0\u202f\u200e\u200f\u061c]/gu, "").normalize("NFKC");
	normalized = replaceAllLiteral(normalized, locale.group, "");
	normalized = replaceAllLiteral(normalized, locale.decimal, ".");
	normalized = replaceAllLiteral(normalized, locale.minus, "-");
	normalized = replaceAllLiteral(normalized, locale.plus, "+");

	for (const [localizedDigit, asciiDigit] of locale.digits) {
		normalized = replaceAllLiteral(normalized, localizedDigit, asciiDigit);
	}

	return normalized;
}

export function parseLocalizedNumberEdit(
	value: string,
	locale: NumberFieldLocale
): ParsedNumberEdit {
	const normalized = normalizeLocalizedEdit(value, locale);
	if (normalized === "") return { kind: "empty" };
	if (/^[+-]$/u.test(normalized) || /^[+-]?\.$/u.test(normalized)) {
		return { kind: "sign" };
	}
	if (!/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)$/u.test(normalized)) {
		return { kind: "invalid" };
	}

	const parsed = Number(normalized);
	if (!Number.isFinite(parsed)) return { kind: "invalid" };
	if (normalized.endsWith(".")) return { kind: "trailing-decimal", value: parsed };
	return { kind: "number", value: parsed };
}

export function formatFocusedNumber(value: number | null, locale: string | string[]): string {
	if (value === null) return "";
	return new Intl.NumberFormat(locale, {
		maximumFractionDigits: NUMBER_FIELD_MAX_PRECISION,
		useGrouping: false,
	}).format(value);
}

export function formatBlurredNumber(
	value: number | null,
	locale: string | string[],
	format: Intl.NumberFormatOptions = {}
): string {
	if (value === null) return "";
	return new Intl.NumberFormat(locale, format).format(value);
}

export function resolveNumberFieldFormat(
	locale: string | string[],
	format: Intl.NumberFormatOptions,
	config: Pick<NumberFieldConfig, "step" | "smallStep" | "largeStep">
): Intl.NumberFormatOptions {
	const configuredPrecision = Math.max(
		decimalPrecision(config.step),
		decimalPrecision(config.smallStep),
		decimalPrecision(config.largeStep)
	);
	const defaultMaximumFractionDigits = Math.max(
		configuredPrecision,
		format.minimumFractionDigits ?? 0
	);
	const resolved =
		format.maximumFractionDigits === undefined
			? {
					...format,
					maximumFractionDigits: defaultMaximumFractionDigits,
				}
			: { ...format };

	try {
		new Intl.NumberFormat(locale, resolved);
		createNumberFieldLocale(locale);
	} catch (error) {
		const reason = error instanceof Error ? error.message : String(error);
		throw new TypeError(`NumberField locale or format is invalid: ${reason}`);
	}

	return resolved;
}

export function serializeInvariantNumber(value: number | null): string {
	return value === null ? "" : String(value);
}

import { getContext, setContext } from "svelte";
import {
	assertNumberFieldValue,
	clampNumberFieldValue,
	createNumberFieldLocale,
	formatBlurredNumber,
	formatFocusedNumber,
	isNumberFieldStepDisabled,
	isNumberFieldValueOutOfBounds,
	type NumberFieldChangeDetails,
	type NumberFieldConfig,
	type NumberFieldDirection,
	type NumberFieldReason,
	parseLocalizedNumberEdit,
	stepNumberFieldValue,
} from "./number-field.js";

export type NumberFieldSize = "sm" | "default" | "lg";

export type NumberFieldState = Readonly<{
	value: number | null;
	config: NumberFieldConfig;
	editValue: string;
	formattedValue: string;
	focused: boolean;
	parseInvalid: boolean;
	validationMessage: string;
	invalid: boolean;
	required: boolean;
	disabled: boolean;
	readonly: boolean;
	allowWheelScrub: boolean;
	inputId: string;
	label?: string;
	hasFieldLabel: boolean;
	hasScrubArea: boolean;
	size: NumberFieldSize;
	form?: string;
	describedBy?: string;
	inputElement: HTMLInputElement | null;
	incrementDisabled: boolean;
	decrementDisabled: boolean;
	beginEdit: () => void;
	endEdit: (sourceEvent: Event | null) => void;
	updateEdit: (value: string, sourceEvent: Event | null) => void;
	commitEdit: (reason: NumberFieldReason, sourceEvent: Event | null) => boolean;
	cancelEdit: () => boolean;
	adjust: (
		direction: NumberFieldDirection,
		amount: number,
		reason: NumberFieldReason,
		sourceEvent: Event | null
	) => boolean;
	adjustByUnits: (
		units: number,
		amount: number,
		reason: NumberFieldReason,
		sourceEvent: Event | null
	) => boolean;
	setToBound: (
		bound: "min" | "max",
		reason: NumberFieldReason,
		sourceEvent: Event | null
	) => boolean;
	commit: (
		reason: NumberFieldReason,
		previousValue: number | null,
		sourceEvent: Event | null
	) => boolean;
	reset: (value: number | null, sourceEvent: Event | null) => void;
	registerScrubArea: () => () => void;
	setInputElement: (element: HTMLInputElement | null) => void;
}>;

type NumberFieldStateOptions = {
	getValue: () => number | null;
	setValue: (value: number | null) => void;
	getConfig: () => NumberFieldConfig;
	getLocale: () => string | string[];
	getFormat: () => Intl.NumberFormatOptions;
	getInputId: () => string;
	getLabel: () => string | undefined;
	getHasFieldLabel: () => boolean;
	getSize: () => NumberFieldSize;
	getForm: () => string | undefined;
	getRequired: () => boolean;
	getDisabled: () => boolean;
	getReadonly: () => boolean;
	getInvalid: () => boolean;
	getAllowWheelScrub: () => boolean;
	getDescribedBy: () => string | undefined;
	getOnValueChange: () =>
		| ((value: number | null, details: NumberFieldChangeDetails) => void)
		| undefined;
	getOnValueCommit: () =>
		| ((value: number | null, details: NumberFieldChangeDetails) => void)
		| undefined;
};

const numberFieldContextKey = Symbol("coss-svelte-number-field");

function localeKey(locale: string | string[]): string {
	return JSON.stringify(Array.isArray(locale) ? locale : [locale]);
}

export function createNumberFieldState(options: NumberFieldStateOptions): NumberFieldState {
	const initialValue = assertNumberFieldValue(options.getValue());
	let editValue = $state(
		formatBlurredNumber(initialValue, options.getLocale(), options.getFormat())
	);
	let focused = $state(false);
	let parseInvalid = $state(false);
	let inputElement = $state<HTMLInputElement | null>(null);
	let scrubAreaCount = $state(0);
	let focusStartValue = initialValue;
	let observedValue = initialValue;
	let editLocale = options.getLocale();
	let observedLocaleKey = localeKey(editLocale);

	function displayValue(value: number | null, editing = focused): string {
		return editing
			? formatFocusedNumber(value, options.getLocale())
			: formatBlurredNumber(value, options.getLocale(), options.getFormat());
	}

	function details(
		reason: NumberFieldReason,
		previousValue: number | null,
		sourceEvent: Event | null
	): NumberFieldChangeDetails {
		return { reason, previousValue, sourceEvent };
	}

	function emitValue(
		nextValue: number | null,
		reason: NumberFieldReason,
		sourceEvent: Event | null
	): boolean {
		assertNumberFieldValue(nextValue);
		const previousValue = options.getValue();
		if (Object.is(previousValue, nextValue)) return false;

		observedValue = nextValue;
		options.setValue(nextValue);
		options.getOnValueChange()?.(nextValue, details(reason, previousValue, sourceEvent));
		return true;
	}

	function beginEdit(): void {
		if (options.getDisabled() || options.getReadonly() || focused) return;
		focused = true;
		parseInvalid = false;
		focusStartValue = options.getValue();
		editLocale = options.getLocale();
		editValue = displayValue(options.getValue(), true);
	}

	function updateEdit(value: string, sourceEvent: Event | null): void {
		editValue = value;
		editLocale = options.getLocale();
		const parsed = parseLocalizedNumberEdit(value, createNumberFieldLocale(editLocale));
		parseInvalid = parsed.kind === "invalid" || parsed.kind === "sign";

		if (parsed.kind === "empty") {
			emitValue(null, "input", sourceEvent);
			return;
		}

		if (parsed.kind === "number" || parsed.kind === "trailing-decimal") {
			emitValue(parsed.value, "input", sourceEvent);
		}
	}

	function commit(
		reason: NumberFieldReason,
		previousValue: number | null,
		sourceEvent: Event | null
	): boolean {
		const value = options.getValue();
		if (Object.is(previousValue, value)) return false;
		options.getOnValueCommit()?.(value, details(reason, previousValue, sourceEvent));
		if (focused) focusStartValue = value;
		return true;
	}

	function commitEdit(reason: NumberFieldReason, sourceEvent: Event | null): boolean {
		if (!focused) return false;
		const parsed = parseLocalizedNumberEdit(editValue, createNumberFieldLocale(editLocale));

		if (parsed.kind === "number" || parsed.kind === "trailing-decimal") {
			emitValue(clampNumberFieldValue(parsed.value, options.getConfig()), reason, sourceEvent);
		} else if (parsed.kind === "empty") {
			emitValue(null, reason, sourceEvent);
		}

		parseInvalid = false;
		editLocale = options.getLocale();
		editValue = displayValue(options.getValue(), true);
		const committed = commit(reason, focusStartValue, sourceEvent);
		focusStartValue = options.getValue();
		return committed;
	}

	function endEdit(sourceEvent: Event | null): void {
		if (!focused) return;
		commitEdit("input", sourceEvent);
		focused = false;
		editValue = displayValue(options.getValue(), false);
	}

	function cancelEdit(): boolean {
		if (!focused) return false;
		const nextValue = displayValue(options.getValue(), true);
		const changed = parseInvalid || editValue !== nextValue;
		parseInvalid = false;
		editLocale = options.getLocale();
		editValue = nextValue;
		return changed;
	}

	function adjust(
		direction: NumberFieldDirection,
		amount: number,
		reason: NumberFieldReason,
		sourceEvent: Event | null
	): boolean {
		if (options.getDisabled() || options.getReadonly()) return false;
		const next = stepNumberFieldValue(options.getValue(), direction, amount, options.getConfig());
		parseInvalid = false;
		const changed = emitValue(next, reason, sourceEvent);
		editLocale = options.getLocale();
		editValue = displayValue(next);
		return changed;
	}

	function adjustByUnits(
		units: number,
		amount: number,
		reason: NumberFieldReason,
		sourceEvent: Event | null
	): boolean {
		if (units === 0) return false;
		const direction: NumberFieldDirection = units < 0 ? -1 : 1;
		let changed = false;
		for (let unit = 0; unit < Math.abs(units); unit += 1) {
			changed = adjust(direction, amount, reason, sourceEvent) || changed;
		}
		return changed;
	}

	function setToBound(
		bound: "min" | "max",
		reason: NumberFieldReason,
		sourceEvent: Event | null
	): boolean {
		if (options.getDisabled() || options.getReadonly()) return false;
		const next = options.getConfig()[bound];
		if (next === undefined) return false;
		parseInvalid = false;
		const changed = emitValue(next, reason, sourceEvent);
		editLocale = options.getLocale();
		editValue = displayValue(next);
		return changed;
	}

	function reset(value: number | null, sourceEvent: Event | null): void {
		const next = assertNumberFieldValue(value, "defaultValue");
		const previousValue = options.getValue();
		parseInvalid = false;
		focused = false;
		editLocale = options.getLocale();
		const changed = emitValue(next, "reset", sourceEvent);
		editValue = displayValue(next, false);
		if (changed) commit("reset", previousValue, sourceEvent);
		focusStartValue = next;
	}

	$effect(() => {
		const value = assertNumberFieldValue(options.getValue());
		if (Object.is(value, observedValue)) return;

		observedValue = value;
		focusStartValue = value;
		if (focused) {
			const parsed = parseLocalizedNumberEdit(editValue, createNumberFieldLocale(editLocale));
			const equivalent =
				(parsed.kind === "empty" && value === null) ||
				((parsed.kind === "number" || parsed.kind === "trailing-decimal") &&
					Object.is(parsed.value, value));
			if (!equivalent) {
				parseInvalid = false;
				editLocale = options.getLocale();
				editValue = displayValue(value, true);
			}
		} else {
			parseInvalid = false;
			editLocale = options.getLocale();
			editValue = displayValue(value, false);
		}
	});

	$effect(() => {
		const nextLocale = options.getLocale();
		const nextLocaleKey = localeKey(nextLocale);
		options.getConfig();
		options.getFormat();

		if (nextLocaleKey !== observedLocaleKey) {
			if (focused) {
				const parsed = parseLocalizedNumberEdit(editValue, createNumberFieldLocale(editLocale));
				if (
					parsed.kind === "empty" ||
					parsed.kind === "number" ||
					parsed.kind === "trailing-decimal"
				) {
					editLocale = nextLocale;
					editValue = displayValue(options.getValue(), true);
				}
			} else {
				editLocale = nextLocale;
				editValue = displayValue(options.getValue(), false);
			}
			observedLocaleKey = nextLocaleKey;
		} else if (!focused) {
			editValue = displayValue(options.getValue(), false);
		}
	});

	$effect(() => {
		inputElement?.setCustomValidity(validationMessage());
	});

	function validationMessage(): string {
		if (options.getDisabled() || options.getReadonly()) return "";
		if (parseInvalid) return "Enter a valid number using the current locale.";
		const value = options.getValue();
		if (options.getRequired() && value === null) return "Enter a number.";
		const { min, max } = options.getConfig();
		if (value !== null && min !== undefined && value < min) {
			return `Value must be greater than or equal to ${min}.`;
		}
		if (value !== null && max !== undefined && value > max) {
			return `Value must be less than or equal to ${max}.`;
		}
		return "";
	}

	return {
		get value() {
			return options.getValue();
		},
		get config() {
			return options.getConfig();
		},
		get editValue() {
			return editValue;
		},
		get formattedValue() {
			return displayValue(options.getValue(), false);
		},
		get focused() {
			return focused;
		},
		get parseInvalid() {
			return parseInvalid;
		},
		get validationMessage() {
			return validationMessage();
		},
		get invalid() {
			return (
				options.getInvalid() ||
				parseInvalid ||
				(!options.getDisabled() &&
					!options.getReadonly() &&
					((options.getRequired() && options.getValue() === null) ||
						isNumberFieldValueOutOfBounds(options.getValue(), options.getConfig())))
			);
		},
		get required() {
			return options.getRequired();
		},
		get disabled() {
			return options.getDisabled();
		},
		get readonly() {
			return options.getReadonly();
		},
		get allowWheelScrub() {
			return options.getAllowWheelScrub();
		},
		get inputId() {
			return options.getInputId();
		},
		get label() {
			return options.getLabel();
		},
		get hasFieldLabel() {
			return options.getHasFieldLabel();
		},
		get hasScrubArea() {
			return scrubAreaCount > 0;
		},
		get size() {
			return options.getSize();
		},
		get form() {
			return options.getForm();
		},
		get describedBy() {
			return options.getDescribedBy();
		},
		get inputElement() {
			return inputElement;
		},
		get incrementDisabled() {
			return isNumberFieldStepDisabled({
				value: options.getValue(),
				direction: 1,
				amount: options.getConfig().step,
				config: options.getConfig(),
				disabled: options.getDisabled(),
				readonly: options.getReadonly(),
			});
		},
		get decrementDisabled() {
			return isNumberFieldStepDisabled({
				value: options.getValue(),
				direction: -1,
				amount: options.getConfig().step,
				config: options.getConfig(),
				disabled: options.getDisabled(),
				readonly: options.getReadonly(),
			});
		},
		beginEdit,
		endEdit,
		updateEdit,
		commitEdit,
		cancelEdit,
		adjust,
		adjustByUnits,
		setToBound,
		commit,
		reset,
		registerScrubArea() {
			scrubAreaCount += 1;
			let registered = true;
			return () => {
				if (!registered) return;
				registered = false;
				scrubAreaCount -= 1;
			};
		},
		setInputElement(element) {
			inputElement = element;
		},
	};
}

export function setNumberFieldContext(context: NumberFieldState): void {
	setContext(numberFieldContextKey, context);
}

export function getNumberFieldContext(): NumberFieldState {
	const context = getContext<NumberFieldState | undefined>(numberFieldContextKey);
	if (!context) {
		throw new Error("Number Field parts must be rendered inside <NumberField>.");
	}
	return context;
}

import type { ClassValue } from "clsx";
import { clsx } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]): string {
	return twMerge(clsx(inputs));
}
